/* Connected Online Learning Workspace
 * Self-contained Canvas artwork. Time is in seconds; the cycle is 20 seconds.
 * Call draw(ctx, time, width, height). Recommended frame rate: 60 fps.
 * Video encoder target and required minimum: 100000000 bits/second (100 Mbps).
 * Verify the encoded video's bitrate in the export application.
 * JavaScript frames themselves do not have a video bitrate.
 */
const ONLINE_LEARNING_SCENE_01 = (() => {
  'use strict';
  const C = {"bg": "#EFF4F5", "paper": "#FFFFFF", "ink": "#263E4D", "muted": "#758E9C", "line": "#CFDCE3", "body": "#F4F8FA", "body2": "#DEE8EE", "side": "#658999", "accent": "#4E9294", "green": "#63947C", "red": "#B37D73", "desk": "#FCFDFB", "desk2": "#DEE8EE"};
  const TAU = Math.PI * 2;
  const fonts = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const measurements = new Map();
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v < .5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
  const phase = (t, a, b) => ease((t - a) / (b - a));
  const mix = (a, b, p) => a + (b - a) * p;
  const travel = (t, a, b, c, d) => phase(t, a, b) * (1 - phase(t, c, d));
  const windowAlpha = (t, a, b, c, d) => travel(t, a, b, c, d);
  function blend(a, b, p) {
    p = clamp(p);
    const ca = parseInt(a.slice(1), 16), cb = parseInt(b.slice(1), 16);
    const r = Math.round(mix(ca >> 16, cb >> 16, p));
    const g = Math.round(mix((ca >> 8) & 255, (cb >> 8) & 255, p));
    const bl = Math.round(mix(ca & 255, cb & 255, p));
    return '#' + ((r << 16) | (g << 8) | bl).toString(16).padStart(6, '0');
  }
  function layer(ctx, opacity, fn) {
    if (opacity <= .00001) return;
    ctx.save(); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function roundedPath(ctx, x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(ctx, x, y, w, h, r, fill, stroke = C.ink, lw = 3) {
    roundedPath(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && lw > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(ctx, x1, y1, x2, y2, color = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke = null, width = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function polygon(ctx, points, fill, stroke = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function matte(ctx, x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w, y + h); g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function label(ctx, value, x, y, size = 20, color = C.ink, align = 'left', maxWidth = 0, weight = 600) {
    const str = String(value);
    let fontSize = size, m;
    while (true) {
      ctx.font = weight + ' ' + fontSize.toFixed(2) + 'px ' + fonts;
      const key = ctx.font + '|' + str;
      m = measurements.get(key);
      if (!m) { const a = ctx.measureText(str); m = {w: a.width, a: a.actualBoundingBoxAscent || fontSize * .75, d: a.actualBoundingBoxDescent || 0}; measurements.set(key, m); }
      if (!maxWidth || m.w <= maxWidth || fontSize <= 12) break;
      fontSize = Math.max(12, fontSize * Math.min(.97, maxWidth / m.w));
    }
    ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.fillText(str, x, y + (m.a - m.d) / 2);
  }
  function check(ctx, x, y, size, color = C.green, p = 1) {
    const pts = [[x - size * .42, y], [x - size * .08, y + size * .30], [x + size * .48, y - size * .32]];
    ctx.beginPath(); ctx.moveTo(...pts[0]);
    if (p < .4) ctx.lineTo(mix(pts[0][0], pts[1][0], p / .4), mix(pts[0][1], pts[1][1], p / .4));
    else { ctx.lineTo(...pts[1]); ctx.lineTo(mix(pts[1][0], pts[2][0], (p - .4) / .6), mix(pts[1][1], pts[2][1], (p - .4) / .6)); }
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(2.5, size * .14); ctx.stroke();
  }
  function activity(ctx, x, y, t, r = 12, color = C.accent) {
    circle(ctx, x, y, r, null, C.line, 2.5);
    const angle = TAU * (t / 5);
    ctx.beginPath(); ctx.arc(x, y, r, angle, angle + Math.PI * .70); ctx.strokeStyle = color; ctx.lineWidth = 3; ctx.stroke();
  }
  const layout = {"x": 0, "y": 0, "w": 1180, "h": 1080, "designWidth": 1180, "designHeight": 1080};
  function heading(ctx, title, subtitle, t) {
    label(ctx, 'ONLINE LEARNING WORKSPACE', 95, 81, 14, C.muted, 'left', 860, 700);
    label(ctx, title, 95, 130, 35, C.ink, 'left', 990, 700);
    label(ctx, subtitle, 95, 176, 18, C.muted, 'left', 982, 400);
    activity(ctx, 1090, 82, t, 11);
  }
  function wave(ctx, x, y, w, h, t, offset = 0, strength = 1) {
    const n = 13, gap = w / (n * 2.4), barW = (w - gap * (n - 1)) / n;
    for (let i = 0; i < n; i++) {
      const a = .32 + .68 * (.5 + .5 * Math.sin(TAU * t / 2.5 + offset + i * .61));
      const hh = Math.max(2, h * a);
      box(ctx, x + i * (barW + gap), y + (h - hh) / 2, barW, hh, Math.min(3, barW / 2), blend(C.line, C.accent, strength), null);
    }
  }
  function monitor(ctx, x, y, w, h, t, fn = learningScreen) {
    const mid = x + w / 2;
    polygon(ctx, [[mid - 29, y + h - 1], [mid + 29, y + h - 1], [mid + 45, y + h + 103], [mid - 45, y + h + 103]], C.body2, C.ink, 3);
    box(ctx, mid - 118, y + h + 100, 236, 18, 8, C.body, C.ink, 3);
    box(ctx, x, y, w, h, 22, matte(ctx, x, y, w, h, C.body, C.body2), C.ink, 4);
    const sx = x + 17, sy = y + 17, sw = w - 34, sh = h - 48;
    box(ctx, sx, sy, sw, sh, 11, C.paper, C.ink, 2);
    ctx.save(); roundedPath(ctx, sx + 1, sy + 1, sw - 2, sh - 2, 10); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    circle(ctx, mid, y + h - 14, 3, C.accent);
    box(ctx, mid - 40, y - 18, 80, 17, 7, C.side, C.ink, 2.5);
    circle(ctx, mid, y - 9.5, 4.5, C.paper, C.ink, 1.5);
    circle(ctx, mid + 26, y - 9.5, 2, C.accent);
  }
  function laptop(ctx, x, y, w, h, t, fn = miniLearning) {
    box(ctx, x, y, w, h, 13, matte(ctx, x, y, w, h, C.body, C.body2), C.ink, 3.5);
    circle(ctx, x + w / 2, y + 7, 2, C.muted);
    const sx = x + 11, sy = y + 17, sw = w - 22, sh = h - 30;
    box(ctx, sx, sy, sw, sh, 6, C.paper, C.ink, 1.5);
    ctx.save(); roundedPath(ctx, sx + 1, sy + 1, sw - 2, sh - 2, 5); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    polygon(ctx, [[x - 23, y + h], [x + w + 23, y + h], [x + w + 12, y + h + 25], [x - 12, y + h + 25]], C.body2, C.ink, 3);
    box(ctx, x + w / 2 - 35, y + h + 5, 70, 9, 3, C.paper, null);
  }
  function tablet(ctx, x, y, w, h, t, fn = miniLearning) {
    box(ctx, x, y, w, h, 22, C.side, C.ink, 3.5);
    const sx = x + 12, sy = y + 16, sw = w - 24, sh = h - 37;
    box(ctx, sx, sy, sw, sh, 12, C.paper, null);
    ctx.save(); roundedPath(ctx, sx, sy, sw, sh, 12); ctx.clip(); fn(ctx, sx, sy, sw, sh, t); ctx.restore();
    line(ctx, x + w / 2 - 22, y + h - 11, x + w / 2 + 22, y + h - 11, C.muted, 2);
  }
  function keyboard(ctx, x = 147, y = 881, w = 435, h = 52) {
    box(ctx, x, y, w, h, 10, C.body, C.ink, 2.5);
    const keyW = (w - 40 - 10 * 7) / 11;
    for (let r = 0; r < 3; r++) for (let c = 0; c < 11; c++) box(ctx, x + 20 + c * (keyW + 7), y + 9 + r * 12, keyW, 7, 2, C.paper, null);
  }
  function desk(ctx) {
    polygon(ctx, [[145, 790], [1018, 790], [1116, 940], [64, 940]], matte(ctx, 64, 790, 1052, 150, C.desk, C.desk2), C.line, 2.5);
    box(ctx, 64, 940, 1052, 17, 5, C.body2, C.ink, 2.5);
    box(ctx, 126, 958, 21, 58, 4, C.body2, C.ink, 2.5);
    box(ctx, 1031, 958, 21, 58, 4, C.body2, C.ink, 2.5);
  }
  function notebook(ctx, x = 850, y = 879, w = 195, h = 47) {
    box(ctx, x, y + 7, w, h, 7, C.paper, C.ink, 2);
    box(ctx, x, y, w, h, 7, blend(C.body, C.accent, .20), C.ink, 2.5);
    line(ctx, x + 16, y + 3, x + 16, y + h - 3, C.muted, 2);
    line(ctx, x + 38, y + 15, x + w - 22, y + 15, C.paper, 2);
    line(ctx, x + 38, y + 27, x + w - 50, y + 27, C.paper, 2);
  }
  function headset(ctx, x = 697, y = 815, scale = 1) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    box(ctx, -5, 6, 10, 91, 4, C.body2, C.ink, 2.5);
    box(ctx, -48, 95, 96, 16, 8, C.body, C.ink, 2.5);
    ctx.beginPath(); ctx.arc(0, 0, 60, Math.PI, TAU); ctx.strokeStyle = C.ink; ctx.lineWidth = 11; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 52, Math.PI + .1, TAU - .1); ctx.strokeStyle = C.body2; ctx.lineWidth = 5; ctx.stroke();
    box(ctx, -66, -8, 24, 64, 11, C.side, C.ink, 2.5);
    box(ctx, 42, -8, 24, 64, 11, C.side, C.ink, 2.5);
    line(ctx, 64, 43, 82, 61, C.ink, 3); line(ctx, 82, 61, 57, 69, C.ink, 3);
    box(ctx, 46, 64, 19, 9, 4, C.side, null);
    ctx.restore();
  }
  function badge(ctx, x, y, w, text, color = C.accent, opacity = 1) {
    box(ctx, x, y, w, 34, 12, blend(C.paper, color, .12), null);
    layer(ctx, opacity, () => label(ctx, text, x + w / 2, y + 17, 14, color, 'center', w - 24, 700));
  }
  function progressBar(ctx,x,y,w,p,color=C.accent,h=6){
    box(ctx,x,y,w,h,h/2,C.line,null);
    if(p>.0001)box(ctx,x,y,w*clamp(p),h,h/2,color,null);
  }
  function tickBox(ctx,x,y,p,size=19){
    box(ctx,x,y,size,size,4,C.paper,C.line,1.5);
    if(p>.0001)check(ctx,x+size/2,y+size/2,size*.64,C.green,p);
  }
  function dock(ctx,x,y,t,w=72,h=38){
    box(ctx,x,y,w,h,9,C.side,C.ink,2.5);
    line(ctx,x+12,y+11,x+w-12,y+11,C.paper,2);
    [0,1,2].forEach(i=>circle(ctx,x+15+i*15,y+h-12,2.5,blend(C.line,C.accent,.55+.25*Math.sin(TAU*t/5+i))));
  }
  function trend(ctx,x,y,w,h,t,offset=0){
    for(let i=1;i<4;i++)line(ctx,x,y+h*i/4,x+w,y+h*i/4,C.line,1);
    const v=u=>.76-.42*u+.07*Math.sin(TAU*u+offset);
    ctx.beginPath();for(let i=0;i<=60;i++){const u=i/60;if(!i)ctx.moveTo(x,y+h*v(u));else ctx.lineTo(x+u*w,y+h*v(u));}
    ctx.strokeStyle=C.accent;ctx.lineWidth=2.5;ctx.stroke();
    const p=.08+.84*(.5-.5*Math.cos(TAU*t/20));circle(ctx,x+p*w,y+h*v(p),4,C.paper,C.accent,2);
  }
  function curvedRoute(ctx,points,t,a,b,color=C.accent){
    ctx.beginPath();ctx.moveTo(...points[0]);ctx.bezierCurveTo(...points[1],...points[2],...points[3]);ctx.strokeStyle=C.line;ctx.lineWidth=2.5;ctx.stroke();
    const alpha=windowAlpha(t,a,a+.55,b-.55,b),p=phase(t,a+.55,b-.55),q=1-p;
    const xx=q*q*q*points[0][0]+3*q*q*p*points[1][0]+3*q*p*p*points[2][0]+p*p*p*points[3][0];
    const yy=q*q*q*points[0][1]+3*q*q*p*points[1][1]+3*q*p*p*points[2][1]+p*p*p*points[3][1];
    layer(ctx,alpha,()=>circle(ctx,xx,yy,4.5,color));
  }
  function clock(ctx,x,y,r,t,hour=9){
    circle(ctx,x,y,r,C.body,C.ink,2.5);for(let i=0;i<12;i++){const a=TAU*i/12;line(ctx,x+Math.sin(a)*r*.80,y-Math.cos(a)*r*.80,x+Math.sin(a)*r*.90,y-Math.cos(a)*r*.90,C.muted,1.5);}
    const a=TAU*t/20,b=TAU*(hour/12);
    line(ctx,x,y,x,y-r*.59,C.ink,2.5);
    line(ctx,x,y,x+Math.sin(a)*r*.77,y-Math.cos(a)*r*.77,C.accent,1.8);
    line(ctx,x,y,x+Math.sin(b)*r*.44,y-Math.cos(b)*r*.44,C.ink,3);circle(ctx,x,y,3,C.ink);
  }

  // All graphics are original geometric paths. No portraits or avatar symbols.
  function learnIcon(ctx, name, x, y, size = 24, color = C.accent) {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 24, size / 24);
    if (name === 'play') {
      polygon(ctx, [[-5,-8],[8,0],[-5,8]], color, null);
    } else if (name === 'book') {
      polygon(ctx,[[-11,-8],[-2,-8],[0,-6],[2,-8],[11,-8],[11,9],[2,9],[0,11],[-2,9],[-11,9]],C.body,color,1.8);
      line(ctx,0,-6,0,10,color,1.8); line(ctx,-7,-3,-3,-3,color,1.3); line(ctx,3,-3,7,-3,color,1.3);
      line(ctx,-7,2,-3,2,color,1.3); line(ctx,3,2,7,2,color,1.3);
    } else if (name === 'search') {
      circle(ctx,-2,-2,7,null,color,2); line(ctx,3,3,10,10,color,2);
    } else if (name === 'code') {
      line(ctx,-5,-7,-11,0,color,2); line(ctx,-11,0,-5,7,color,2);
      line(ctx,5,-7,11,0,color,2); line(ctx,11,0,5,7,color,2); line(ctx,2,-10,-2,10,color,2);
    } else if (name === 'calendar') {
      box(ctx,-10,-8,20,18,3,null,color,2); line(ctx,-9,-2,9,-2,color,1.8);
      line(ctx,-5,-11,-5,-6,color,2); line(ctx,5,-11,5,-6,color,2);
      box(ctx,-5,2,4,4,1,color,null); box(ctx,2,2,4,4,1,color,null);
    } else if (name === 'folder') {
      polygon(ctx,[[-11,-7],[-2,-7],[1,-3],[11,-3],[11,9],[-11,9]],C.body,color,1.8);
    } else if (name === 'file') {
      polygon(ctx,[[-8,-11],[3,-11],[9,-5],[9,11],[-8,11]],C.paper,color,1.8);
      line(ctx,3,-11,3,-5,color,1.5); line(ctx,3,-5,9,-5,color,1.5);
      line(ctx,-4,0,5,0,color,1.4); line(ctx,-4,4,5,4,color,1.4); line(ctx,-4,8,1,8,color,1.4);
    } else if (name === 'chart') {
      line(ctx,-10,10,11,10,color,1.7);
      box(ctx,-8,0,4,8,1,color,null); box(ctx,-1,-5,4,13,1,color,null); box(ctx,6,-10,4,18,1,color,null);
    } else if (name === 'certificate') {
      box(ctx,-11,-8,22,16,2,C.paper,color,1.8);
      line(ctx,-6,-3,6,-3,color,1.4); line(ctx,-6,1,3,1,color,1.4);
      check(ctx,6,5,5,color);
    } else {
      for(let i=0;i<3;i++){ circle(ctx,-8,-7+i*7,1.4,color); line(ctx,-3,-7+i*7,10,-7+i*7,color,1.7); }
    }
    ctx.restore();
  }
  function screenHeader(ctx,x,y,w,title,t) {
    label(ctx,title,x+18,y+23,16,C.ink,'left',w-78,700);
    activity(ctx,x+w-26,y+22,t,8);
    line(ctx,x+16,y+43,x+w-16,y+43,C.line,1.5);
  }
  function sidebar(ctx,x,y,h,t) {
    box(ctx,x,y,34,h,8,C.body,null);
    const names=['book','list','chart','calendar'];
    names.forEach((name,i)=>{
      const p=.20+.35*(.5+.5*Math.sin(TAU*t/20-i*1.4));
      box(ctx,x+6,y+10+i*44,22,28,5,blend(C.body,C.accent,p*.22),null);
      learnIcon(ctx,name,x+17,y+24+i*44,17,blend(C.muted,C.accent,p));
    });
  }
  function thumbnail(ctx,x,y,w,h,type,t,offset=0) {
    box(ctx,x,y,w,h,7,blend(C.body,C.accent,.045),null);
    if(type===0){
      const ww=w*.24,hh=h*.40,yy=y+(h-hh)/2;
      box(ctx,x+w*.12,yy,ww,hh,4,C.paper,C.line,1.4);
      line(ctx,x+w*.36,yy+hh/2,x+w*.54,yy+hh/2,C.muted,1.5);
      box(ctx,x+w*.54,yy,w*.29,hh,4,blend(C.paper,C.accent,.20),C.accent,1.4);
      circle(ctx,x+w*.23,yy+hh/2,4,C.accent);
      const u=.5-.5*Math.cos(TAU*t/10+offset);
      circle(ctx,x+w*.39+u*w*.12,yy+hh/2,2.7,C.accent);
    }else if(type===1){
      const base=y+h*.77;
      for(let i=0;i<5;i++){
        const bh=h*(.24+i*.06+.025*Math.sin(TAU*t/10+i+offset));
        box(ctx,x+w*.16+i*w*.14,base-bh,w*.08,bh,2,i===3?C.accent:C.side,null);
      }
      line(ctx,x+w*.13,base+3,x+w*.87,base+3,C.line,1.5);
    }else{
      const a=TAU*t/20+offset,r=Math.min(w,h)*.23;
      circle(ctx,x+w*.48,y+h*.5,r,null,C.side,2.5);
      box(ctx,x+w*.70,y+h*.31,w*.10,h*.38,3,C.accent,null);
      circle(ctx,x+w*.48+Math.cos(a)*r,y+h*.5+Math.sin(a)*r,3.7,C.paper,C.accent,1.5);
    }
  }
  function courseCard(ctx,x,y,w,h,title,type,t,p=.45) {
    box(ctx,x,y,w,h,10,C.paper,C.line,1.5);
    thumbnail(ctx,x+10,y+10,w-20,h-52,type,t,type*.7);
    label(ctx,title,x+12,y+h-30,13,C.ink,'left',w-24,700);
    progressBar(ctx,x+12,y+h-15,w-24,p,C.accent,4);
  }
  function ring(ctx,x,y,r,p,t) {
    circle(ctx,x,y,r,null,C.line,7);
    const a=-Math.PI/2;
    ctx.beginPath();ctx.arc(x,y,r,a,a+TAU*clamp(p));ctx.strokeStyle=C.accent;ctx.lineWidth=7;ctx.stroke();
    const aa=TAU*t/20;
    circle(ctx,x+Math.cos(aa)*(r+12),y+Math.sin(aa)*(r+12),2.4,C.muted);
  }
  function learningScreen(ctx,x,y,w,h,t) {
    screenHeader(ctx,x,y,w,'COURSE DASHBOARD',t);
    sidebar(ctx,x+16,y+60,h-79,t);
    const xx=x+65,ww=w-82,cw=(ww-22)/3,p=travel(t,2,11,16,19.8);
    ['Design systems','Data essentials','Digital strategy'].forEach((v,i)=>courseCard(ctx,xx+i*(cw+11),y+60,cw,112,v,i,t,.34+.18*i+.15*p));
    label(ctx,'LEARNING PROGRESS',xx,y+195,13,C.muted,'left',ww*.65,700);
    label(ctx,'3 ACTIVE COURSES',xx+ww,y+195,12,C.accent,'right',ww*.32,700);
    progressBar(ctx,xx,y+213,ww,.38+.24*p);
    const yy=y+239,hh=h-263,left=ww*.62;
    box(ctx,xx,yy,left,hh,10,C.body,C.line,1.3);
    label(ctx,'Weekly activity',xx+13,yy+19,13,C.ink,'left',left-26,600);
    trend(ctx,xx+14,yy+36,left-28,Math.max(25,hh-48),t,.5);
    box(ctx,xx+left+12,yy,ww-left-12,hh,10,C.body,C.line,1.3);
